export const fiberInterruptAs: {
  (
    fiberId: number | undefined,
    annotations?: Context.Context<never> | undefined
  ): <A, E>(self: Fiber.Fiber<A, E>) => Effect.Effect<void>
  <A, E>(
    self: Fiber.Fiber<A, E>,
    fiberId: number | undefined,
    annotations?: Context.Context<never> | undefined
  ): Effect.Effect<void>
} = dual(
  (args) => hasProperty(args[0], FiberTypeId),
  <A, E>(
    self: Fiber.Fiber<A, E>,
    fiberId: number | undefined,
    annotations?: Context.Context<never> | undefined
  ): Effect.Effect<void> =>
    withFiber((parent) => {
      let ann = fiberStackAnnotations(parent)
      ann = ann && annotations ? Context.merge(ann, annotations) : ann ?? annotations
      self.interruptUnsafe(fiberId, ann)
      return asVoid(fiberAwait(self))
    })
)

export const uninterruptible = <A, E, R>(
  self: Effect.Effect<A, E, R>
): Effect.Effect<A, E, R> =>
  withFiber((fiber) => {
    if (!fiber.interruptible) return self
    fiber.interruptible = false
    fiber._stack.push(setInterruptibleTrue)
    return self
  })

const setInterruptible: (interruptible: boolean) => Primitive = makePrimitive({
  op: "SetInterruptible",
  [contAll](fiber) {
    fiber.interruptible = this[args]
    if (fiber._interruptedCause && fiber.interruptible) {
      return () => failCause(fiber._interruptedCause!)
    }
  }
})
const setInterruptibleTrue = setInterruptible(true)
const setInterruptibleFalse = setInterruptible(false)

const setFiberInterruptible = (fiber: FiberImpl): Effect.Effect<never> | undefined => {
  fiber.interruptible = true
  fiber._stack.push(setInterruptibleFalse)
  if (fiber._interruptedCause) return failCause(fiber._interruptedCause)
}

export const takeUnsafe = <A, E>(self: Dequeue<A, E>): Exit<A, E> | undefined => {
  if (self.state._tag === "Done") {
    return self.state.exit
  }
  if (self.messages.length > 0) {
    const message = MutableList.take(self.messages)!
    releaseCapacity(self)
    return core.exitSucceed(message)
  } else if (self.capacity <= 0 && self.state.offers.size > 0) {
    self.capacity = 1
    releaseCapacity(self)
    self.capacity = 0
    const message = MutableList.take(self.messages)!
    releaseCapacity(self)
    return core.exitSucceed(message)
  }
  return undefined

export const doneUnsafe = <A, E>(self: Deferred<A, E>, effect: Effect<A, E>): boolean => {
  if (self.effect) return false
  self.effect = effect
  if (self.resumes) {
    // Clear `resumes` before resuming: a waiter resumed with an interrupt
    // cause dies synchronously inside `resume`, and its await cleanup would
    // otherwise splice this array mid-iteration and skip the next waiter.
    const resumes = self.resumes
    self.resumes = undefined
    for (let i = 0; i < resumes.length; i++) {
      resumes[i](effect)
    }
  }
  return true

